commands.command:
install -m 700 -d /root/.ssh
printf '%s
' "$CLUSTER_SSH_PRIVKEY" > /root/.ssh/id_ed25519
chmod 600 /root/.ssh/id_ed25519
[ -s /etc/infra-update.key ] || tsig-keygen -a hmac-sha256 infra-update > /etc/infra-update.key
[ -s /etc/infra-transfer.key ] || tsig-keygen -a hmac-sha256 infra-transfer > /etc/infra-transfer.key
chown root:named /etc/infra-update.key /etc/infra-transfer.key
chmod 640 /etc/infra-update.key /etc/infra-transfer.key
install -d -o named -g named -m 770 /var/named/dynamic
cat > /var/named/dynamic/infra.test <<'ANTRIEB_ZONE'
$TTL 60
@ IN SOA node1.infra.test. hostmaster.infra.test. (
  2026100101 60 30 1209600 60 )
  IN NS node1.infra.test.
  IN NS node2.infra.test.
  IN NS node3.infra.test.
node1 IN A 10.100.205.10
node2 IN A 10.100.205.11
node3 IN A 10.100.205.12
app IN A 10.100.205.10
status IN TXT "ready"
ANTRIEB_ZONE
chown named:named /var/named/dynamic/infra.test
chmod 640 /var/named/dynamic/infra.test
cat > /etc/named.conf <<'ANTRIEB_NAMED'
options {
    listen-on port 53 { 127.0.0.1; 10.100.205.10; };
    listen-on-v6 { none; };
    directory "/var/named";
    pid-file "/run/named/named.pid";
    session-keyfile "/run/named/session.key";
    managed-keys-directory "/var/named/dynamic";
    allow-query { any; };
    recursion no;
};
include "/etc/infra-update.key";
include "/etc/infra-transfer.key";
zone "infra.test" IN {
    type primary;
    file "dynamic/infra.test";
    allow-update { key "infra-update"; };
    allow-transfer { key "infra-transfer"; };
    notify yes;
    also-notify {
        10.100.205.11 key "infra-transfer";
        10.100.205.12 key "infra-transfer";
    };
    dnssec-policy default;
    inline-signing yes;
};
ANTRIEB_NAMED
restorecon -RF /etc/named.conf /etc/infra-update.key /etc/infra-transfer.key /var/named/dynamic
named-checkconf -z /etc/named.conf
named-checkzone infra.test /var/named/dynamic/infra.test
printf 'primary-config-valid; credentials generated locally and not displayed\n'

chown root:named /etc/infra-transfer.key
chmod 640 /etc/infra-transfer.key
install -d -o named -g named -m 770 /var/named/slaves
cat > /etc/named.conf <<'ANTRIEB_NAMED'
options {
    listen-on port 53 { 127.0.0.1; NODE_ADDR; };
    listen-on-v6 { none; };
    directory "/var/named";
    pid-file "/run/named/named.pid";
    session-keyfile "/run/named/session.key";
    allow-query { any; };
    recursion no;
};
include "/etc/infra-transfer.key";
server 10.100.205.10 {
    keys { "infra-transfer"; };
};
zone "infra.test" IN {
    type secondary;
    file "slaves/infra.test";
    primaries { 10.100.205.10 key "infra-transfer"; };
    allow-notify { key "infra-transfer"; };
    allow-transfer { none; };
};
ANTRIEB_NAMED
sed -i "s/NODE_ADDR/$NODE_IP/" /etc/named.conf
restorecon -RF /etc/named.conf /etc/infra-transfer.key /var/named/slaves
named-checkconf /etc/named.conf
printf 'secondary-config-valid %s %s\n' "$NODE_NAME" "$NODE_IP"

chown root:named /etc/infra-transfer.key
chmod 640 /etc/infra-transfer.key
install -d -o named -g named -m 770 /var/named/slaves
cat > /etc/named.conf <<'ANTRIEB_NAMED'
options {
    listen-on port 53 { 127.0.0.1; NODE_ADDR; };
    listen-on-v6 { none; };
    directory "/var/named";
    pid-file "/run/named/named.pid";
    session-keyfile "/run/named/session.key";
    allow-query { any; };
    recursion no;
};
include "/etc/infra-transfer.key";
server 10.100.205.10 {
    keys { "infra-transfer"; };
};
zone "infra.test" IN {
    type secondary;
    file "slaves/infra.test";
    primaries { 10.100.205.10 key "infra-transfer"; };
    allow-notify { key "infra-transfer"; };
    allow-transfer { none; };
};
ANTRIEB_NAMED
sed -i "s/NODE_ADDR/$NODE_IP/" /etc/named.conf
restorecon -RF /etc/named.conf /etc/infra-transfer.key /var/named/slaves
named-checkconf /etc/named.conf
printf 'secondary-config-valid %s %s\n' "$NODE_NAME" "$NODE_IP"

cat > /etc/named.conf <<'ANTRIEB_NAMED'
options {
    listen-on port 53 { 127.0.0.1; 10.100.205.13; };
    listen-on-v6 { none; };
    directory "/var/named";
    pid-file "/run/named/named.pid";
    session-keyfile "/run/named/session.key";
    allow-query { any; };
    recursion yes;
    dnssec-validation no;
};
zone "infra.test" IN {
    type forward;
    forward only;
    forwarders {
        10.100.205.11;
        10.100.205.12;
    };
};
ANTRIEB_NAMED
named-checkconf /etc/named.conf
con_name=$(nmcli -t -f NAME,DEVICE connection show --active | awk -F: '$2 != "lo" {print $1; exit}')
if [ -n "$con_name" ]; then nmcli connection modify "$con_name" ipv4.ignore-auto-dns yes ipv4.dns "$NODE_IP"; fi
printf 'nameserver %s\noptions timeout:2 attempts:2\n' "$NODE_IP" > /etc/resolv.conf
restorecon /etc/named.conf /etc/resolv.conf
printf 'resolver-config-valid; forwarders=node2,node3; system-resolver=%s\n' "$NODE_IP"
